import{_ as e,o as r,c as l,a2 as n}from"./chunks/framework.Nk14N-ai.js";const y=JSON.parse('{"title":"Kinetic Error Handbook","description":"","frontmatter":{},"headers":[],"relativePath":"error_handbook.md","filePath":"error_handbook.md"}'),o={name:"error_handbook.md"};function d(a,t,s,i,g,c){return r(),l("div",null,[...t[0]||(t[0]=[n('<h1 id="kinetic-error-handbook" tabindex="-1">Kinetic Error Handbook <a class="header-anchor" href="#kinetic-error-handbook" aria-label="Permalink to &quot;Kinetic Error Handbook&quot;">​</a></h1><p>This document serves as the official reference for the Kinetic protocol&#39;s error codes (<code>KIN-*</code>). The daemon and API use these stable error codes to communicate problems to clients in an RFC 7807-compatible JSON format.</p><p>Below is the complete taxonomy of errors you might encounter when interacting with the Kinetic API, along with their HTTP status mappings and user-facing explanations.</p><hr><h2 id="name-resolution-errors-kin-res" tabindex="-1">Name Resolution Errors (<code>KIN-RES-*</code>) <a class="header-anchor" href="#name-resolution-errors-kin-res" aria-label="Permalink to &quot;Name Resolution Errors (`KIN-RES-*`)&quot;">​</a></h2><p>Errors that occur when attempting to resolve a <code>.kin</code> domain via the DHT.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-RES-001</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Offline</strong>: You appear to be offline. The node cannot connect to the P2P network to resolve names.</td><td style="text-align:left;">Node has no connected DHT peers.</td></tr><tr><td style="text-align:left;"><strong>KIN-RES-002</strong></td><td style="text-align:left;"><code>404 Not Found</code></td><td style="text-align:left;"><strong>Not Found</strong>: The domain is not registered on the Kinetic network.</td><td style="text-align:left;">Lookups failed after checking multiple peers.</td></tr><tr><td style="text-align:left;"><strong>KIN-RES-003</strong></td><td style="text-align:left;"><code>422 Unprocessable Entity</code></td><td style="text-align:left;"><strong>Cryptographic Verification Failed</strong>: The name was found, but the record has an invalid cryptographic proof, indicating potential tampering.</td><td style="text-align:left;">The VDF proof embedded in the record was rejected.</td></tr><tr><td style="text-align:left;"><strong>KIN-RES-004</strong></td><td style="text-align:left;"><code>410 Gone</code></td><td style="text-align:left;"><strong>Registration Expired</strong>: The name&#39;s registration has expired. The owner needs to renew it.</td><td style="text-align:left;">Record age in drand rounds exceeds the maximum validity window.</td></tr><tr><td style="text-align:left;"><strong>KIN-RES-005</strong></td><td style="text-align:left;"><code>504 Gateway Timeout</code></td><td style="text-align:left;"><strong>Resolution Timeout</strong>: The network took too long to respond. Please try again.</td><td style="text-align:left;">Query exceeded the internal DHT timeout threshold.</td></tr><tr><td style="text-align:left;"><strong>KIN-RES-006</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Internal Resolution Error</strong>: An internal network error occurred during resolution.</td><td style="text-align:left;">Unhandled internal logic panic or storage failure.</td></tr></tbody></table><hr><h2 id="name-publishing-errors-kin-pub" tabindex="-1">Name Publishing Errors (<code>KIN-PUB-*</code>) <a class="header-anchor" href="#name-publishing-errors-kin-pub" aria-label="Permalink to &quot;Name Publishing Errors (`KIN-PUB-*`)&quot;">​</a></h2><p>Errors that occur when attempting to write a new or updated record to the DHT.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-PUB-001</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Offline</strong>: Cannot publish because the node is offline.</td><td style="text-align:left;">No active DHT peers available for <code>PUT</code>.</td></tr><tr><td style="text-align:left;"><strong>KIN-PUB-002</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid VDF Proof</strong>: The computational proof of work attached to the publish request is invalid and was rejected.</td><td style="text-align:left;">The <code>chiavdf</code> verifier failed.</td></tr><tr><td style="text-align:left;"><strong>KIN-PUB-003</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Name Already Owned</strong>: The requested <code>.kin</code> name is already registered under a different public key.</td><td style="text-align:left;">Ed25519 signature mismatch on existing valid record.</td></tr><tr><td style="text-align:left;"><strong>KIN-PUB-004</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Publish Failed</strong>: The network rejected all DHT publish attempts.</td><td style="text-align:left;">Every single <code>PUT</code> request failed across the routing table.</td></tr><tr><td style="text-align:left;"><strong>KIN-PUB-005</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Internal Publish Error</strong>: An unexpected internal error occurred during the publish flow.</td><td style="text-align:left;">Storage or configuration error prevented publishing.</td></tr></tbody></table><hr><h2 id="registration-lifecycle-errors-kin-reg" tabindex="-1">Registration Lifecycle Errors (<code>KIN-REG-*</code>) <a class="header-anchor" href="#registration-lifecycle-errors-kin-reg" aria-label="Permalink to &quot;Registration Lifecycle Errors (`KIN-REG-*`)&quot;">​</a></h2><p>Errors that occur during the end-to-end domain registration (Commit/Reveal) process.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-REG-001</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid Name</strong>: Name contains invalid characters. Use only lowercase letters, digits, and hyphens.</td><td style="text-align:left;">Failed regex/UTF-8 validation checks.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-002</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>VDF Computation Failed</strong>: The heavy mathematical computation failed locally.</td><td style="text-align:left;">The underlying <code>chiavdf</code> engine panicked or encountered an error.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-003</strong></td><td style="text-align:left;"><code>422 Unprocessable Entity</code></td><td style="text-align:left;"><strong>Commitment Mismatch</strong>: The registration data is inconsistent with the previously broadcast hash.</td><td style="text-align:left;">The Phase 2 Reveal hash did not match the Phase 1 Commit hash.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-004</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Already Owned</strong>: The name is already registered by someone else.</td><td style="text-align:left;">Front-running defense triggered.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-005</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Registration In Progress</strong>: A registration is already actively computing for this name.</td><td style="text-align:left;">Only one VDF task per name is permitted concurrently.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-006</strong></td><td style="text-align:left;"><code>422 Unprocessable Entity</code></td><td style="text-align:left;"><strong>Registration Rejected</strong>: The network actively rejected the registration attempt.</td><td style="text-align:left;">See <code>reject_reason</code> in error details.</td></tr><tr><td style="text-align:left;"><strong>KIN-REG-007</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Internal Registration Error</strong>: An unexpected issue occurred during registration.</td><td style="text-align:left;">Catch-all for IO or state errors during the flow.</td></tr></tbody></table><hr><h2 id="governance-errors-kin-gov" tabindex="-1">Governance Errors (<code>KIN-GOV-*</code>) <a class="header-anchor" href="#governance-errors-kin-gov" aria-label="Permalink to &quot;Governance Errors (`KIN-GOV-*`)&quot;">​</a></h2><p>Errors related to on-chain OTA updates and Council voting logic.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-GOV-001</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Missing Root Key</strong>: Fatal configuration error. <code>ROOT_PUBLIC_KEY_HEX</code> is not set.</td><td style="text-align:left;">Node missing Founder Key config.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-002</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Missing Guard Key</strong>: Fatal configuration error. <code>GUARD_PUBLIC_KEY_HEX</code> is not set.</td><td style="text-align:left;">Node missing Veto Key config.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-003</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Key Length Mismatch</strong>: A supplied public key is not exactly 32 bytes.</td><td style="text-align:left;">Malformed Ed25519 input.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-004</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Stale Proposal</strong>: The governance action is too old and was rejected to prevent replay attacks.</td><td style="text-align:left;">Timestamp outside the allowable replay window.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-005</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Timelock Not Expired</strong>: The governance action is still in its mandatory waiting period.</td><td style="text-align:left;">Action attempted before <code>unlock_time</code>.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-006</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>OTA Timelock Not Expired</strong>: The 24-hour waiting period for binary replacement has not elapsed.</td><td style="text-align:left;">Network safety delay active.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-007</strong></td><td style="text-align:left;"><code>409 Conflict</code></td><td style="text-align:left;"><strong>Not Pending Or Vetoed</strong>: The target hash is not in a pending state or was actively vetoed by the Guard.</td><td style="text-align:left;">Action aborted or non-existent.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-008</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Council Size Mismatch</strong>: The proposer claimed an artificially low denominator to bypass the 69% threshold.</td><td style="text-align:left;">Invalid signature pool structure.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-009</strong></td><td style="text-align:left;"><code>401 Unauthorized</code></td><td style="text-align:left;"><strong>Invalid Guard Signature</strong>: The veto signature provided by the Guard key is invalid.</td><td style="text-align:left;">Crypto verification failed.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-010</strong></td><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;"><strong>Emergency Reset Vetoed</strong>: The Emergency Reset has been permanently vetoed.</td><td style="text-align:left;">Reset action aborted.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-011</strong></td><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;"><strong>Emergency Reset Requires Root</strong>: The reset action lacks a valid Founder signature.</td><td style="text-align:left;">Unauthorized privileged action.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-012</strong></td><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;"><strong>Emergency Reset Requires Guard</strong>: The reset action (without override) lacks a valid Guard signature.</td><td style="text-align:left;">Unauthorized privileged action.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-013</strong></td><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;"><strong>Rotate Requires Guard</strong>: A Root key rotation requires a Guard co-signature.</td><td style="text-align:left;">Unauthorized privileged action.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-014</strong></td><td style="text-align:left;"><code>501 Not Implemented</code></td><td style="text-align:left;"><strong>Unhandled Threshold Math</strong>: The requested threshold math is not supported by the council voting logic.</td><td style="text-align:left;">Logic bug or unknown feature flag.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-015</strong></td><td style="text-align:left;"><code>403 Forbidden</code></td><td style="text-align:left;"><strong>Empty Council</strong>: The council is empty; actions must be performed by the Root Key.</td><td style="text-align:left;">Phase 1 fallback triggered on Phase 2 node.</td></tr><tr><td style="text-align:left;"><strong>KIN-GOV-016</strong></td><td style="text-align:left;"><code>401 Unauthorized</code></td><td style="text-align:left;"><strong>Insufficient Signatures</strong>: The action does not have the required 69% valid supermajority.</td><td style="text-align:left;">Threshold voting failed.</td></tr></tbody></table><hr><h2 id="network-client-peer-errors-kin-net" tabindex="-1">Network Client &amp; Peer Errors (<code>KIN-NET-*</code>) <a class="header-anchor" href="#network-client-peer-errors-kin-net" aria-label="Permalink to &quot;Network Client &amp; Peer Errors (`KIN-NET-*`)&quot;">​</a></h2><p>Errors originating from the libp2p transport and Kademlia DHT layers.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-NET-001</strong></td><td style="text-align:left;"><code>504 Gateway Timeout</code></td><td style="text-align:left;"><strong>Request Timed Out</strong>: A network request exceeded its deadline.</td><td style="text-align:left;">Local or remote timeout triggered.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-002</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Node is Offline</strong>: Node has no reachable peers.</td><td style="text-align:left;">Swarm disconnected.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-003</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Routing Table Empty</strong>: The Kademlia routing table contains no known peers.</td><td style="text-align:left;">DHT bootstrap failed or no peers discovered.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-004</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Internal Channel Closed</strong>: Communication between the API thread and the P2P loop broke down.</td><td style="text-align:left;">Async task panic or drop.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-005</strong></td><td style="text-align:left;"><code>504 Gateway Timeout</code></td><td style="text-align:left;"><strong>Stream Dropped</strong>: The remote peer closed the connection before fully responding.</td><td style="text-align:left;">Premature EOF.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-006</strong></td><td style="text-align:left;"><code>501 Not Implemented</code></td><td style="text-align:left;"><strong>Unsupported Protocol</strong>: Remote peer does not speak the requested Kinetic protocol version.</td><td style="text-align:left;">Protocol mismatch during negotiation.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-007</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>Gossipsub Error</strong>: Failed to publish or subscribe to a GossipSub topic.</td><td style="text-align:left;">Network propagation failed.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-008</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Store Error</strong>: The local Kademlia record store threw an error.</td><td style="text-align:left;">Memory/DB access failure.</td></tr><tr><td style="text-align:left;"><strong>KIN-NET-009</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Other Network Error</strong>: A miscellaneous transport error.</td><td style="text-align:left;">Uncategorized libp2p error.</td></tr></tbody></table><hr><h2 id="storage-engine-errors-kin-sto" tabindex="-1">Storage Engine Errors (<code>KIN-STO-*</code>) <a class="header-anchor" href="#storage-engine-errors-kin-sto" aria-label="Permalink to &quot;Storage Engine Errors (`KIN-STO-*`)&quot;">​</a></h2><p>Errors emitted by the embedded <code>sled</code> database engine.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-STO-001</strong></td><td style="text-align:left;"><code>423 Locked</code></td><td style="text-align:left;"><strong>Database Locked</strong>: Another instance of the Kinetic daemon is already running.</td><td style="text-align:left;">Process lock file collision.</td></tr><tr><td style="text-align:left;"><strong>KIN-STO-002</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Storage Corruption</strong>: The local database structure has been corrupted.</td><td style="text-align:left;">Automatic backup &amp; reset triggered.</td></tr><tr><td style="text-align:left;"><strong>KIN-STO-003</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Operation Failed</strong>: A read/write operation failed at the engine level.</td><td style="text-align:left;">Disk IO or thread panic inside Sled.</td></tr></tbody></table><hr><h2 id="ota-auto-updater-errors-kin-ota" tabindex="-1">OTA Auto-Updater Errors (<code>KIN-OTA-*</code>) <a class="header-anchor" href="#ota-auto-updater-errors-kin-ota" aria-label="Permalink to &quot;OTA Auto-Updater Errors (`KIN-OTA-*`)&quot;">​</a></h2><p>Errors related to the Over-The-Air binary hot-swapping mechanism.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-OTA-001</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>No Mirrors Provided</strong>: Update failed because no download URLs were provided by the council.</td><td style="text-align:left;">Empty mirror array in <code>SignedGovernanceMessage</code>.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-002</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>HTTP Status Error</strong>: Update failed due to a server error (HTTP code).</td><td style="text-align:left;">Target HTTP server returned 4xx/5xx.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-003</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>Network Error</strong>: Update failed due to a transport error during download.</td><td style="text-align:left;">TCP/TLS failure.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-004</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>Reqwest Error</strong>: Internal HTTP client failed to initialize or execute.</td><td style="text-align:left;"><code>reqwest</code> crate error.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-005</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>I/O Error</strong>: Issue writing the new binary version to disk.</td><td style="text-align:left;">File permission or space issue.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-006</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Self Replace Error</strong>: The node failed to seamlessly replace itself with the updated binary.</td><td style="text-align:left;"><code>self_replace</code> crate failure.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-007</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Hash Mismatch</strong>: Downloaded software did not match the expected cryptographic hash.</td><td style="text-align:left;">Download corruption or supply chain attack.</td></tr><tr><td style="text-align:left;"><strong>KIN-OTA-008</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Spawn Failed</strong>: Update succeeded, but the node failed to restart automatically.</td><td style="text-align:left;"><code>Command::new</code> failure.</td></tr></tbody></table><hr><h2 id="verifiable-delay-function-vdf-errors-kin-vdf" tabindex="-1">Verifiable Delay Function (VDF) Errors (<code>KIN-VDF-*</code>) <a class="header-anchor" href="#verifiable-delay-function-vdf-errors-kin-vdf" aria-label="Permalink to &quot;Verifiable Delay Function (VDF) Errors (`KIN-VDF-*`)&quot;">​</a></h2><p>Errors occurring during intense CPU math tasks and Class Group cryptography.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-VDF-001</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Lock File Error</strong>: Failed to create the VDF lock file to serialize heavy tasks.</td><td style="text-align:left;">Permission/IO error in <code>~/.kinetic</code>.</td></tr><tr><td style="text-align:left;"><strong>KIN-VDF-002</strong></td><td style="text-align:left;"><code>503 Service Unavailable</code></td><td style="text-align:left;"><strong>Lock Acquire Error</strong>: Failed to acquire the VDF lock due to timeout or OS failure.</td><td style="text-align:left;">Another thread is hogging the CPU for too long.</td></tr><tr><td style="text-align:left;"><strong>KIN-VDF-003</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Discriminant Error</strong>: Failed to cryptographically map the network challenge to a valid prime discriminant.</td><td style="text-align:left;">Class group initialization error.</td></tr><tr><td style="text-align:left;"><strong>KIN-VDF-004</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Proof Generation Error</strong>: The chiavdf prover threw an internal error and failed.</td><td style="text-align:left;">Math panic inside C++ bindings.</td></tr><tr><td style="text-align:left;"><strong>KIN-VDF-005</strong></td><td style="text-align:left;"><code>501 Not Implemented</code></td><td style="text-align:left;"><strong>Unsupported Platform</strong>: VDF operation is unsupported on this OS/Architecture.</td><td style="text-align:left;">chiavdf binary missing for architecture.</td></tr></tbody></table><hr><h2 id="drand-quicknet-errors-kin-dra" tabindex="-1">Drand Quicknet Errors (<code>KIN-DRA-*</code>) <a class="header-anchor" href="#drand-quicknet-errors-kin-dra" aria-label="Permalink to &quot;Drand Quicknet Errors (`KIN-DRA-*`)&quot;">​</a></h2><p>Errors occurring during Drand randomness beacon fetches and cache operations.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-DRA-001</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>All Endpoints Failed</strong>: All configured Drand endpoints returned errors or timed out.</td><td style="text-align:left;">Could not reach any healthy nodes.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-002</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>Network Error</strong>: A network-level error occurred while fetching Drand pulse.</td><td style="text-align:left;">DNS failure or connection refused.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-003</strong></td><td style="text-align:left;"><code>* Upstream Error</code></td><td style="text-align:left;"><strong>HTTP Status Error</strong>: A Drand endpoint returned a non-2xx HTTP status.</td><td style="text-align:left;">The specific status is dynamic.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-004</strong></td><td style="text-align:left;"><code>404 Not Found</code></td><td style="text-align:left;"><strong>No Cached Pulse</strong>: No pulse was found in the local cache, and the network is unavailable.</td><td style="text-align:left;">Offline cache miss.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-005</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Serialization Error</strong>: JSON (de)serialization of the Drand pulse failed.</td><td style="text-align:left;">Payload format changed or corrupted.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-006</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Storage Error</strong>: A local storage engine error occurred while reading or writing the pulse cache.</td><td style="text-align:left;">Engine read/write failed.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-007</strong></td><td style="text-align:left;"><code>502 Bad Gateway</code></td><td style="text-align:left;"><strong>Reqwest Error</strong>: An HTTP client error occurred.</td><td style="text-align:left;"><code>reqwest</code> internal error.</td></tr><tr><td style="text-align:left;"><strong>KIN-DRA-008</strong></td><td style="text-align:left;"><code>422 Unprocessable Entity</code></td><td style="text-align:left;"><strong>Invalid Drand Signature</strong>: The BLS threshold signature was mathematically invalid.</td><td style="text-align:left;">Possible tampering or corrupted beacon.</td></tr></tbody></table><hr><h2 id="dns-validation-errors-kin-dns" tabindex="-1">DNS Validation Errors (<code>KIN-DNS-*</code>) <a class="header-anchor" href="#dns-validation-errors-kin-dns" aria-label="Permalink to &quot;DNS Validation Errors (`KIN-DNS-*`)&quot;">​</a></h2><p>Errors occurring when parsing or validating <code>.kin</code> DNS zone files and records.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-DNS-001</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Nested Too Deeply</strong>: The JSON payload has too many nested structures.</td><td style="text-align:left;">JSON recursion depth exceeded 10.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-002</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Parse Error</strong>: The payload is not valid JSON or does not match the DnsZone schema.</td><td style="text-align:left;"><code>serde_json</code> error.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-003</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Too Many Records</strong>: The zone contains more than the maximum 50 allowed records.</td><td style="text-align:left;">Anti-bloat limit enforcement.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-004</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid Label Length</strong>: A label is empty or longer than 63 characters.</td><td style="text-align:left;">Follows DNS RFC limits.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-005</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid Label Characters</strong>: A label contains non-alphanumeric characters or starts/ends with a hyphen.</td><td style="text-align:left;">Follows DNS RFC limits.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-006</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid CNAME Configuration</strong>: A CNAME record was provided alongside other records for the same label.</td><td style="text-align:left;">RFC violation.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-007</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>TXT Record Too Long</strong>: A TXT record exceeds the maximum allowed length of 255 bytes.</td><td style="text-align:left;">Anti-bloat limit enforcement.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-008</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid CNAME Target</strong>: A CNAME target is empty or longer than 253 characters.</td><td style="text-align:left;">Follows DNS RFC limits.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-009</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid PeerId</strong>: The string could not be parsed into a valid libp2p PeerId.</td><td style="text-align:left;">Invalid base58 encoding.</td></tr><tr><td style="text-align:left;"><strong>KIN-DNS-010</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid KID</strong>: The string does not start with the required <code>did:kin:</code> prefix.</td><td style="text-align:left;">DID syntax validation.</td></tr></tbody></table><hr><h2 id="identity-seed-errors-kin-idn" tabindex="-1">Identity &amp; Seed Errors (<code>KIN-IDN-*</code>) <a class="header-anchor" href="#identity-seed-errors-kin-idn" aria-label="Permalink to &quot;Identity &amp; Seed Errors (`KIN-IDN-*`)&quot;">​</a></h2><p>Errors related to node identity keypairs and mnemonic seed phrases.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Error Code</th><th style="text-align:left;">HTTP Status</th><th style="text-align:left;">Meaning</th><th style="text-align:left;">Developer Detail</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>KIN-IDN-001</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>I/O Error</strong>: An OS-level error occurred reading or writing the identity file.</td><td style="text-align:left;">File permissions or disk issue.</td></tr><tr><td style="text-align:left;"><strong>KIN-IDN-002</strong></td><td style="text-align:left;"><code>500 Internal Server Error</code></td><td style="text-align:left;"><strong>Corrupted Identity File</strong>: The loaded identity file does not contain exactly 32 bytes.</td><td style="text-align:left;">Truncated or modified key file.</td></tr><tr><td style="text-align:left;"><strong>KIN-IDN-003</strong></td><td style="text-align:left;"><code>404 Not Found</code></td><td style="text-align:left;"><strong>Identity Not Found</strong>: The local identity file could not be found.</td><td style="text-align:left;"><code>kinetic-cli seed init</code> has not been run.</td></tr><tr><td style="text-align:left;"><strong>KIN-IDN-004</strong></td><td style="text-align:left;"><code>400 Bad Request</code></td><td style="text-align:left;"><strong>Invalid Seed Phrase</strong>: The provided seed phrase is not a valid BIP-39 mnemonic.</td><td style="text-align:left;">Typo or invalid dictionary word.</td></tr></tbody></table>',47)])])}const h=e(o,[["render",d]]);export{y as __pageData,h as default};
